// Catalog of tmux options shown in the glossary/options editor.
// scope: server | session | window | pane   type: bool | number | enum | string | colour | style | key
// managed: true -> generated by the visual status bar designer instead of edited directly.

const o = (name, scope, type, def, cat, desc, tags = [], extra = {}) => ({ name, scope, type, def, cat, desc, tags, ...extra });

